existing = bc.get_existing_names_for_theme('Animes & Desenhos')
seen = set()
valid_animes = []
for item in MORE_ANIMES:
    name = item[0]
    norm = bc.normalize_name(name)
    if norm not in existing and norm not in seen:
        seen.add(norm)
        valid_animes.append(item)

print('Valid extra animes count:', len(valid_animes))

with open('scripts/generators/gen_animes_extra.py', 'a', encoding='utf-8') as f:
    for item in valid_animes:
        f.write(f'EXTRA_ANIMES.append({repr(item)})\n')

